100	    /// die sich zuvor nur im Element-/Property-Typ unterschied. `fromList` wrappt das deserialisierte
101	    /// `List&lt;TItem&gt;` in `TCollection` beim Aufrufer statt per ungesichertem `(TCollection)(object)`-Cast,
102	    /// der nur zufällig funktioniert, wenn `List&lt;TItem&gt;` tatsächlich in `TCollection` konvertierbar ist.
103	    /// </summary>
104	    private static void ConfigureJsonListConversion<TCollection, TItem>(
105	        PropertyBuilder<TCollection> property,
106	        Func<List<TItem>, TCollection> fromList)
107	        where TCollection : class, IReadOnlyCollection<TItem>
108	    {
109	        var empty = fromList(new List<TItem>());
110	
111	        property
112	            .HasConversion(
113	                v => JsonSerializer.Serialize(v, JsonSerializerOptions.Default),
114	                v => fromList(JsonSerializer.Deserialize<List<TItem>>(v, JsonSerializerOptions.Default) ?? new List<TItem>()))
115	            .Metadata.SetValueComparer(new ValueComparer<TCollection>(
116	                (a, b) => (a ?? empty).SequenceEqual(b ?? empty),
117	                v => (v ?? empty).Aggregate(0, (hash, item) => HashCode.Combine(hash, item)),
118	                v => fromList((v ?? empty).ToList())));
119	    }
