1	using System.Text.Json;
2	using Microsoft.EntityFrameworkCore;
3	using seed_a_backend.Api.Domain;
4	using seed_a_backend.Api.Infrastructure.SeedModels;
5	
6	namespace seed_a_backend.Api.Infrastructure;
7	
8	public class SeedDataImporter(AppDbContext db)
9	{
10	    private static readonly JsonSerializerOptions JsonOptions = new() { PropertyNameCaseInsensitive = true };
11	
12	    public async Task ImportIfEmptyAsync(string jsonFilePath, CancellationToken ct = default)
13	    {
14	        if (await db.Venues.AnyAsync(ct))
15	        {
16	            return;
17	        }
18	
19	        if (!File.Exists(jsonFilePath))
20	        {
21	            throw new InvalidOperationException($"Anfangsdatenbestand '{jsonFilePath}' wurde nicht gefunden.");
22	        }
23	
24	        var json = await File.ReadAllTextAsync(jsonFilePath, ct);
25	        SeedDataDto? data;
26	        try
27	        {
28	            data = JsonSerializer.Deserialize<SeedDataDto>(json, JsonOptions);
29	        }
30	        catch (JsonException ex)
31	        {
32	            throw new InvalidOperationException(
33	                $"Anfangsdatenbestand '{jsonFilePath}' konnte nicht gelesen werden: {ex.Message}", ex);
34	        }
35	
36	        if (data is null)
37	        {
38	            throw new InvalidOperationException($"Anfangsdatenbestand konnte nicht aus '{jsonFilePath}' gelesen werden.");
39	        }
40	
41	        await ImportAsync(data, ct);
42	    }
43	
44	    public async Task ImportAsync(SeedDataDto data, CancellationToken ct = default)
45	    {
46	        var spielstaetten = data.Spielstaetten
47	            ?? throw new InvalidOperationException("Anfangsdatenbestand enthält kein 'spielstaetten'-Feld.");
48	        var veranstaltungen = data.Veranstaltungen
49	            ?? throw new InvalidOperationException("Anfangsdatenbestand enthält kein 'veranstaltungen'-Feld.");
50	
51	        var venueIds = new HashSet<string>();
52	        foreach (var venueDto in spielstaetten)
53	        {
54	            var venueId = RequireNonNull(venueDto.Id, "Anfangsdatenbestand enthält eine Spielstätte mit fehlender (null) Id.");
55	            if (!venueIds.Add(venueId))
56	            {
57	                throw new InvalidOperationException($"Spielstätte '{venueId}' ist im Anfangsdatenbestand mehrfach vorhanden.");
58	            }
59	        }
60	
61	        foreach (var eventDto in veranstaltungen)
62	        {
63	            var spielstaetteId = RequireNonNull(eventDto.SpielstaetteId, $"Veranstaltung '{eventDto.Id}' hat eine fehlende (null) Spielstätten-Id.");
64	            if (!venueIds.Contains(spielstaetteId))
65	            {
66	                throw new InvalidOperationException(
67	                    $"Veranstaltung '{eventDto.Id}' referenziert unbekannte Spielstätte '{spielstaetteId}'.");
68	            }
69	        }
70	
71	        var venues = new List<Venue>();
72	
73	        foreach (var venueDto in spielstaetten)
74	        {
75	            var venueId = RequireNonNull(venueDto.Id, "Anfangsdatenbestand enthält eine Spielstätte mit fehlender (null) Id.");
76	            var venueName = RequireNonNull(venueDto.Name, $"Spielstätte '{venueId}' hat einen fehlenden (null) Namen.");
77	            var venue = new Venue { Name = venueName };
78	            var roomsById = new Dictionary<string, Room>();
79	
80	            var raeume = venueDto.Raeume
81	                ?? throw new InvalidOperationException($"Spielstätte '{venueId}' enthält kein 'raeume'-Feld.");
82	
83	            foreach (var roomDto in raeume)
84	            {
85	                var roomId = RequireNonNull(roomDto.Id, $"Spielstätte '{venueId}' enthält einen Raum mit fehlender (null) Id.");
86	                var roomName = RequireNonNull(roomDto.Name, $"Raum '{roomId}' in Spielstätte '{venueId}' hat einen fehlenden (null) Namen.");
87	
88	                if (roomDto.Spalten < 1)
89	                {
90	                    throw new InvalidOperationException(
91	                        $"Raum '{roomId}' in Spielstätte '{venueId}' hat eine ungültige Spaltenzahl ({roomDto.Spalten}); erwartet wird mindestens 1.");
92	                }
93	
94	                var aisleColumns = roomDto.Gang?.Spalten ?? new List<int>();
95	                foreach (var column in aisleColumns)
96	                {
97	                    if (column < 1 || column > roomDto.Spalten)
98	                    {
99	                        throw new InvalidOperationException(
100	                            $"Raum '{roomId}': Gang-Spalte '{column}' liegt außerhalb des Sitzplans (1..{roomDto.Spalten}).");
101	                    }
102	                }
103	
104	                var reihen = roomDto.Reihen
105	                    ?? throw new InvalidOperationException($"Raum '{roomId}' in Spielstätte '{venueId}' enthält kein 'reihen'-Feld.");
106	                var rowLabels = reihen
107	                    .Select(rowLabel => RequireNonNull(
108	                        rowLabel, $"Raum '{roomId}' in Spielstätte '{venueId}' enthält einen leeren (null) Eintrag in 'reihen'."))
109	                    .ToList();
110	
111	                if (!roomsById.TryAdd(roomId, new Room
112	                {
113	                    Name = roomName,
114	                    RowLabels = rowLabels,
115	                    ColumnCount = roomDto.Spalten,
116	                    AisleColumns = aisleColumns,
117	                }))
118	                {
119	                    throw new InvalidOperationException(
120	                        $"Spielstätte '{venueId}' enthält den Raum '{roomId}' mehrfach.");
121	                }
122	
123	                venue.Rooms.Add(roomsById[roomId]);
124	            }
125	
126	            foreach (var eventDto in veranstaltungen.Where(e => e.SpielstaetteId == venueId))
127	            {
128	                var raumId = RequireNonNull(eventDto.RaumId, $"Veranstaltung '{eventDto.Id}' hat eine fehlende (null) Raum-Id.");
129	                if (!roomsById.TryGetValue(raumId, out var room))
130	                {
131	                    throw new InvalidOperationException(
132	                        $"Veranstaltung '{eventDto.Id}' referenziert unbekannten Raum '{raumId}' in Spielstätte '{venueId}'.");
133	                }
134	
135	                if (eventDto.DauerMinuten < 1)
136	                {
137	                    throw new InvalidOperationException(
138	                        $"Veranstaltung '{eventDto.Id}' hat eine ungültige Dauer ({eventDto.DauerMinuten} Minuten); erwartet wird mindestens 1.");
139	                }
140	
141	                if (eventDto.Altersfreigabe < 0)
142	                {
143	                    throw new InvalidOperationException(
144	                        $"Veranstaltung '{eventDto.Id}' hat eine ungültige Altersfreigabe ({eventDto.Altersfreigabe}); negative Werte sind nicht erlaubt.");
145	                }
146	
147	                var @event = new Event
148	                {
149	                    Titel = RequireNonNull(eventDto.Titel, $"Veranstaltung '{eventDto.Id}' hat einen fehlenden (null) Titel."),
150	                    Beschreibung = RequireNonNull(eventDto.Beschreibung, $"Veranstaltung '{eventDto.Id}' hat eine fehlende (null) Beschreibung."),
151	                    Zeitpunkt = eventDto.Zeitpunkt,
152	                    DauerMinuten = eventDto.DauerMinuten,
153	                    Altersfreigabe = eventDto.Altersfreigabe,
154	                };
155	
156	                var preiskategorien = eventDto.Preiskategorien
157	                    ?? throw new InvalidOperationException($"Veranstaltung '{eventDto.Id}' enthält kein 'preiskategorien'-Feld.");
158	
159	                foreach (var priceCategoryDto in preiskategorien)
160	                {
161	                    if (priceCategoryDto.Preis < 0)
162	                    {
163	                        throw new InvalidOperationException(
164	                            $"Veranstaltung '{eventDto.Id}': Preiskategorie '{priceCategoryDto.Id}' hat einen negativen Preis ({priceCategoryDto.Preis}).");
165	                    }
166	
167	                    @event.PriceCategories.Add(new PriceCategory
168	                    {
169	                        Name = RequireNonNull(
170	                            priceCategoryDto.Name,
171	                            $"Veranstaltung '{eventDto.Id}': Preiskategorie '{priceCategoryDto.Id}' hat einen fehlenden (null) Namen."),
172	                        Preis = priceCategoryDto.Preis,
173	                    });
174	                }
175	
176	                var belegteSitzplaetze = eventDto.BelegteSitzplaetze
177	                    ?? throw new InvalidOperationException($"Veranstaltung '{eventDto.Id}' enthält kein 'belegteSitzplaetze'-Feld.");
178	
179	                var gesehen = new HashSet<(string RowLabel, int ColumnNumber)>();
180	                foreach (var sitzplatz in belegteSitzplaetze)
181	                {
182	                    if (sitzplatz is null)
183	                    {
184	                        throw new FormatException(
185	                            $"Veranstaltung '{eventDto.Id}' enthält einen leeren (null) Eintrag in 'belegteSitzplaetze'.");
186	                    }
187	
188	                    var (rowLabel, columnNumber) = ParseSitzplatz(sitzplatz);
189	
190	                    if (!gesehen.Add((rowLabel, columnNumber)))
191	                    {
192	                        throw new InvalidOperationException(
193	                            $"Veranstaltung '{eventDto.Id}' listet den Sitzplatz '{sitzplatz}' mehrfach in 'belegteSitzplaetze'.");
194	                    }
195	
196	                    if (!room.RowLabels.Contains(rowLabel))
197	                    {
198	                        throw new InvalidOperationException(
199	                            $"Veranstaltung '{eventDto.Id}': Sitzplatz '{sitzplatz}' referenziert die unbekannte Reihe '{rowLabel}' in Raum '{eventDto.RaumId}'.");
200	                    }
201	
202	                    if (columnNumber < 1 || columnNumber > room.ColumnCount)
203	                    {
204	                        throw new InvalidOperationException(
205	                            $"Veranstaltung '{eventDto.Id}': Sitzplatz '{sitzplatz}' liegt außerhalb der Spaltenzahl (1..{room.ColumnCount}) von Raum '{eventDto.RaumId}'.");
206	                    }
207	
208	                    if (room.AisleColumns.Contains(columnNumber))
209	                    {
210	                        throw new InvalidOperationException(
211	                            $"Veranstaltung '{eventDto.Id}': Sitzplatz '{sitzplatz}' liegt auf einer Gang-Spalte von Raum '{eventDto.RaumId}'.");
212	                    }
213	
214	                    @event.BookingPositions.Add(new BookingPosition
215	                    {
216	                        RowLabel = rowLabel,
217	                        ColumnNumber = columnNumber,
218	                        BookingId = null,
219	                        PriceCategoryId = null,
220	                        CancelledAtUtc = null,
221	                    });
222	                }
223	
224	                room.Events.Add(@event);
225	            }
226	
227	            venues.Add(venue);
228	        }
229	
230	        db.Venues.AddRange(venues);
231	        await db.SaveChangesAsync(ct);
232	    }
233	
234	    /// <summary>
235	    /// `required`-Felder in den Seed-DTOs erzwingen bei System.Text.Json nur die Anwesenheit des
236	    /// JSON-Schlüssels, nicht dessen Nicht-Null-Wert — ein expliziter JSON-`null`-Wert bleibt also
