import { Component, inject, signal } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { DatePipe } from '@angular/common';
import { HttpErrorResponse } from '@angular/common/http';

import { EventsApiService } from '../../core/api/events-api.service';
import { EventDetail } from '../../core/api/event-detail';

@Component({
  selector: 'app-event-detail',
  imports: [DatePipe],
  templateUrl: './event-detail.html',
  styleUrl: './event-detail.scss'
})
export class EventDetailPage {
  private readonly route = inject(ActivatedRoute);
  private readonly eventsApi = inject(EventsApiService);

  readonly event = signal<EventDetail | null>(null);
  readonly loading = signal(true);
  readonly notFound = signal(false);
  readonly loadError = signal(false);

  constructor() {
    const id = Number(this.route.snapshot.paramMap.get('id'));
    // Backend-Route ist `{id:int}` (Int32) — größere Werte matchen dort keine Action und liefern
    // ein envelope-loses Framework-404 statt EVENT_NOT_FOUND, daher hier bereits abfangen.
    if (!Number.isInteger(id) || id > 2147483647) {
      this.loading.set(false);
      this.notFound.set(true);
      return;
    }

    this.eventsApi.getEvent(id).subscribe({
      next: event => {
        this.event.set(event);
        this.loading.set(false);
      },
      error: (err: HttpErrorResponse) => {
        this.loading.set(false);
        if (err.error?.code === 'EVENT_NOT_FOUND') {
          this.notFound.set(true);
        } else {
          this.loadError.set(true);
        }
      }
    });
  }
}

@if (loading()) {
  <p class="event-detail__loading">Veranstaltung wird geladen…</p>
} @else if (notFound()) {
  <p class="event-detail__error" role="alert">Veranstaltung nicht gefunden.</p>
} @else if (loadError()) {
  <p class="event-detail__error" role="alert">Veranstaltungsdetails konnten nicht geladen werden. Bitte versuchen Sie es später erneut.</p>
} @else if (event(); as e) {
  <article class="event-detail">
    <h1 class="event-detail__title">{{ e.titel }}</h1>
    <p class="event-detail__description">{{ e.beschreibung }}</p>
    <dl class="event-detail__meta">
      <dt>Spielstätte</dt>
      <dd>{{ e.spielstaette }}</dd>
      <dt>Raum</dt>
      <dd>{{ e.raum }}</dd>
      <dt>Zeitpunkt</dt>
      <dd>{{ e.zeitpunkt | date:'EEEE, d. MMMM y, HH:mm' }} Uhr</dd>
      <dt>Dauer</dt>
      <dd>{{ e.dauerMinuten }} Minuten</dd>
      <dt>Altersfreigabe</dt>
      <dd>{{ e.altersfreigabe === 0 ? 'Keine Altersbeschränkung' : 'Ab ' + e.altersfreigabe + ' Jahren' }}</dd>
    </dl>
  </article>
}

