2	
3	import { EventsApiService } from '../../core/api/events-api.service';
4	import { EventSummary } from '../../core/api/event-summary';
5	import { VenuesApiService } from '../../core/api/venues-api.service';
6	import { Venue } from '../../core/api/venue';
7	import { EventCard } from './event-card/event-card';
8	import { EventFilterBar } from './event-filter-bar/event-filter-bar';
9	
10	@Component({
11	  selector: 'app-program-overview',
12	  imports: [EventCard, EventFilterBar],
13	  templateUrl: './program-overview.html',
14	  styleUrl: './program-overview.scss'
15	})
16	export class ProgramOverview {
17	  private readonly eventsApi = inject(EventsApiService);
18	  private readonly venuesApi = inject(VenuesApiService);
19	
20	  readonly events = signal<EventSummary[]>([]);
21	  readonly loading = signal(true);
22	  readonly loadError = signal(false);
23	  readonly von = signal<string | null>(null);
24	  readonly bis = signal<string | null>(null);
25	  readonly venueId = signal<number | null>(null);
26	  readonly venues = signal<Venue[]>([]);
27	
28	  constructor() {
29	    this.venuesApi.getVenues().subscribe(venues => this.venues.set(venues));
30	
31	    effect(onCleanup => {
32	      const von = this.von();
33	      const bis = this.bis();
34	      const venueId = this.venueId();
35	      this.loading.set(true);
36	      this.loadError.set(false);
37	      const subscription = this.eventsApi.getEvents({ von, bis, venueId }).subscribe({
38	        next: events => {
39	          this.events.set(events);
40	          this.loading.set(false);
